export const BODY_LANGUAGE_TONE_ACTIVITIES = [
{n:1,type:"mcq",micro:"Apa itu bahasa tubuh",q:"'Bahasa tubuh' adalah...",options:["Pesan yang kamu kirim lewat wajah, mata, postur, gerakan tangan, & jarak tubuh — tanpa kata","Bahasa daerah tertentu yang dipakai orang di suatu wilayah untuk berbicara sehari-hari","Cara menulis dengan rapi, bersih, dan indah di atas kertas ketika sedang mengerjakan tugas"],answer:0,explain:"Sebagian besar kesan pertama datang dari sinyal non-verbal, bukan kata-kata.",hint:"Pesan tanpa kata lewat tubuh, atau bahasa lisan?"},
{n:2,type:"mcq",micro:"Apa itu nada suara",q:"'Nada suara' (intonasi) adalah...",options:["Isi kalimat yang kamu ucapkan, yaitu makna dari kata-kata yang kamu pilih saat berbicara kepada orang lain","Cara kalimat diucapkan: tinggi-rendah, keras-pelan, cepat-lambat, hangat-dingin","Jumlah kata dalam kalimat yang kamu ucapkan, makin banyak kata berarti nadanya makin tinggi dan lebih kuat"],answer:1,explain:"Kalimat yang sama ('oh, kamu datang') bisa terdengar ramah, kaget, atau sinis tergantung nadanya.",hint:"Isi kata, atau cara mengucapkannya?"},
{n:3,type:"mcq",micro:"Pesan konsisten",q:"Komunikasi terasa paling jujur & jelas ketika...",options:["Kata-katanya ramah, tetapi wajahnya cemberut dan matanya menghindar dari lawan bicara","Nadanya marah, tetapi kata-kata yang keluar hanyalah 'aku tidak apa-apa kok, sungguh'","Kata, nada, & bahasa tubuh menyampaikan pesan yang sama"],answer:2,explain:"Saat ketiganya cocok, pendengar percaya. Saat bertentangan, pendengar bingung & cenderung memercayai sinyal tubuh/nada.",hint:"Ketiganya sejalan, atau saling bertentangan?"},
{n:4,type:"mcq",micro:"Kontak mata",q:"Kontak mata yang wajar saat berbicara menunjukkan...",options:["Kamu hadir, jujur, & memperhatikan","Kamu sedang bosan","Kamu menantang lawan bicara"],answer:0,explain:"Bukan menatap tajam tanpa henti — cukup melihat mata lawan bicara secara berkala dengan santai.",hint:"Hadir & memperhatikan, atau menantang?"},
{n:5,type:"mcq",micro:"Senyum",q:"Senyum yang tulus saat menyapa membuat lawan bicara...",options:["Tidak merasakan apa-apa","Merasa disambut & lebih nyaman","Merasa dicurigai"],answer:1,explain:"Senyum adalah sinyal 'aman, ramah' yang dipahami hampir semua orang.",hint:"Menyambut, atau menakuti?"},
{n:6,type:"mcq",micro:"Postur terbuka",q:"'Postur terbuka' (bahu rileks, tangan tidak menyilang erat, menghadap lawan bicara) menyampaikan...",options:["Kamu mengantuk","Kamu tertutup & menolak","Kamu terbuka untuk berbicara & mendengar"],answer:2,explain:"Postur tertutup (menyilangkan tangan, memunggungi) sering terbaca sebagai menjaga jarak atau tidak setuju.",hint:"Terbuka untuk bicara, atau menutup diri?"},
{n:7,type:"mcq",micro:"Anggukan",q:"Menganggukkan kepala perlahan saat orang bicara berarti...",options:["Menunjukkan kamu mengikuti & memahami","Menantang mereka","Menyuruh mereka diam"],answer:0,explain:"Anggukan kecil adalah 'lampu hijau' yang membuat pembicara nyaman melanjutkan.",hint:"Mengikuti, atau menghentikan?"},
{n:8,type:"mcq",micro:"Jarak tubuh",q:"Berdiri terlalu dekat dengan orang yang baru dikenal biasanya membuatnya...",options:["Merasa nyaman","Merasa terdesak / tidak nyaman","Merasa dihormati"],answer:1,explain:"Tiap orang punya 'ruang pribadi'. Beri jarak yang sopan, terutama dengan orang baru.",hint:"Nyaman, atau terdesak?"},
{n:9,type:"order",micro:"Menyapa dengan tubuh yang ramah",q:"Urutkan cara menyapa seseorang dengan bahasa tubuh yang ramah.",items:["Hadapkan badan ke arah orang itu","Buat kontak mata & tersenyum","Sapa dengan nada hangat: 'Halo, apa kabar?'","Beri jarak nyaman & postur terbuka saat mengobrol"],answer:[0,1,2,3],explain:"Menghadap → mata & senyum → sapaan hangat → jarak & postur nyaman. Tubuh menyapa sebelum kata.",hint:"Apa yang tubuhmu lakukan sebelum kamu bicara?"},
{n:10,type:"mcq",micro:"Nada pertanyaan vs perintah",q:"Kalimat 'tolong tutup pintunya' terdengar sopan bila diucapkan dengan nada...",options:["Berbisik menakutkan","Tinggi & membentak","Tenang & ramah, sedikit naik di akhir"],answer:2,explain:"Nada tenang mengubah permintaan jadi ajakan, bukan bentakan.",hint:"Membentak, atau tenang & ramah?"},
{n:11,type:"tf",micro:"Wajah menyampaikan perasaan",q:"Benar atau Salah: Ekspresi wajah (alis, mulut, mata) sering menyampaikan perasaan seseorang bahkan sebelum ia mengucapkan sepatah kata.",answer:true,explain:"Wajah bergerak cepat & jujur. Orang membaca wajahmu lebih dulu daripada kata-katamu.",hint:"Wajah bicara duluan, atau kata duluan?"},
{n:12,type:"tf",micro:"Bahasa tubuh tidak penting?",q:"Benar atau Salah: Selama kata-katamu sopan, bahasa tubuh & nada suara tidak berpengaruh pada bagaimana pesanmu diterima.",answer:false,explain:"Sebaliknya, nada mengejek atau wajah cemberut bisa membatalkan kata-kata sopan. Sinyal non-verbal sangat berpengaruh.",hint:"Kata sopan cukup, atau nada & wajah juga menentukan?"},
{n:13,type:"mcq",micro:"Menghadap saat diajak bicara",q:"Saat seseorang mengajakmu bicara & kamu tetap menghadap layar HP, pesan yang terkirim:",options:["'Kamu kurang penting daripada layarku'","'Aku sedang fokus mendengarkanmu'","'Kamu penting bagiku'"],answer:0,explain:"Tubuh yang tidak menghadap berkata 'perhatianku di tempat lain', betapapun kamu berkata 'lanjut, aku dengar'.",hint:"Apa arti tidak menghadap orang yang bicara?"},
{n:14,type:"mcq",micro:"Nada monoton",q:"Berbicara dengan nada datar tanpa naik-turun sama sekali membuat pendengar...",options:["Sangat bersemangat","Sulit tetap fokus & sulit menangkap bagian yang penting","Merasa dihargai"],answer:1,explain:"Variasi nada menandai mana yang penting & menjaga perhatian. Monoton membuat semua terdengar sama.",hint:"Menjaga fokus, atau membuat mengantuk?"},
{n:15,type:"mcq",micro:"Gestur tangan",q:"Gerakan tangan yang wajar saat menjelaskan (mis. menunjuk arah, menggambarkan ukuran)...",options:["Membuat kamu terlihat gugup selalu","Selalu mengganggu","Membantu memperjelas & menunjukkan kamu bersemangat pada topik"],answer:2,explain:"Gestur yang sesuai isi memperkuat pesan. Gestur berlebihan atau tidak nyambung baru mengganggu.",hint:"Sesuai isi = membantu atau mengganggu?"},
{n:16,type:"mcq",micro:"Nada saat minta maaf",q:"Meminta maaf dengan nada terburu-buru & mata melihat ke tempat lain sering terasa...",options:["Tidak tulus / sekadar formalitas","Sangat mengharukan","Tulus"],answer:0,explain:"Permintaan maaf terasa tulus bila nada tenang, wajah menghadap, & tubuh tidak buru-buru pergi.",hint:"Terburu-buru + mata mengelak = tulus?"},
{n:17,type:"mcq",micro:"Membaca tanda 'tidak nyaman'",q:"Lawan bicara mundur selangkah, menyilangkan tangan, & menjawab pendek-pendek. Kemungkinan besar ia...",options:["Sedang sangat senang dan ingin dekat denganmu serta mengobrol lebih lama lagi","Merasa tidak nyaman atau ingin mengakhiri pembicaraan","Ingin kamu bicara lebih lama dan berdiri lebih dekat karena ia mulai tertarik padamu"],answer:1,explain:"Membaca sinyal ini membantumu menyesuaikan diri: beri jarak, kurangi tekanan, atau tanyakan apakah waktunya kurang tepat.",hint:"Mundur + tangan menyilang + jawaban pendek — nyaman atau tidak?"},
{n:18,type:"mcq",micro:"Nada & volume di tempat umum",q:"Berbicara di perpustakaan atau saat orang lain sedang fokus, nada & volume yang tepat:",options:["Normal saja seperti di lapangan","Berbisik dramatis yang malah menarik perhatian","Pelan & singkat, atau tunda sampai keluar ruangan"],answer:2,explain:"Menyesuaikan volume dengan tempat & situasi adalah bagian dari komunikasi yang sopan.",hint:"Menyesuaikan tempat, atau volume yang sama di mana-mana?"},
{n:19,type:"mcq",micro:"Ekspresi saat menerima kabar",q:"Teman dengan bangga menunjukkan hasil karyanya. Bahasa tubuh yang mendukung:",options:["Melihat karyanya, tersenyum, & berkata dengan nada hangat 'wah, bagus!'","Melirik sekilas karyanya sambil terus menatap layar HP dan berkata 'oh, iya' dengan nada datar","Memasang wajah datar tanpa reaksi apa pun sambil diam dan tidak berkata sepatah kata pun kepadanya"],answer:0,explain:"Perhatian tubuh + nada hangat membuat apresiasimu terasa sungguh-sungguh.",hint:"Melihat + senyum + nada hangat, atau melirik sekilas?"},
{n:20,type:"open",micro:"Membaca satu adegan",q:"Di kantin, Adit menghampiri meja teman-temannya. Ia berdiri agak jauh, tangan di saku, bahu turun, dan hanya berkata pelan 'boleh gabung?' sambil melihat ke lantai. Jelaskan apa yang mungkin dirasakan Adit dari bahasa tubuh & nadanya, dan tulis bagaimana teman-temannya bisa merespons dengan bahasa tubuh yang menyambut.",explain:"Jawaban baik menafsirkan sinyal Adit (ragu/malu/tidak yakin diterima) dari jarak, postur, suara, dan arah pandang, lalu menyebut respons bahasa tubuh menyambut yang konkret: menghadap, senyum, kontak mata, menggeser tempat/menepuk kursi, nada hangat.",hint:"Perhatikan jarak, postur bahu, arah pandang, volume suara — lalu pikirkan sinyal 'kamu diterima'.",sample:"Dari bahasa tubuhnya (berdiri jauh, tangan di saku, bahu turun, suara pelan, melihat ke lantai), Adit kemungkinan merasa ragu, malu, atau tidak yakin apakah ia diterima. Ia menahan diri, seolah siap ditolak. Teman-temannya bisa merespons dengan bahasa tubuh yang menyambut: menoleh dan menghadapkan badan ke arahnya, tersenyum, menggeser tempat duduk sambil berkata dengan nada hangat 'Boleh banget, sini duduk!', dan menepuk kursi di sebelah. Kontak mata yang ramah dan senyum memberi sinyal 'kamu diterima di sini', yang meredakan keraguannya jauh lebih cepat daripada sekadar kata 'boleh'."},
{n:21,type:"classify",micro:"Sinyal terbuka vs tertutup",q:"Kelompokkan tiap sinyal tubuh ke 'Terbuka/menyambut' atau 'Tertutup/menjaga jarak'.",items:["Menghadap lawan bicara, bahu rileks","Menyilangkan tangan erat & memunggungi","Kontak mata ramah & anggukan","Melihat jam berulang & badan mengarah ke pintu"],groups:["Terbuka/menyambut","Tertutup/menjaga jarak"],answer:{"Terbuka/menyambut":["Menghadap lawan bicara, bahu rileks","Kontak mata ramah & anggukan"],"Tertutup/menjaga jarak":["Menyilangkan tangan erat & memunggungi","Melihat jam berulang & badan mengarah ke pintu"]},explain:"Terbuka: tubuh menghadap & rileks, mata terhubung. Tertutup: tubuh terhalang, mengarah pergi, perhatian ke tempat lain.",hint:"Tubuh mengundang, atau tubuh menjauh?"},
{n:22,type:"mcq",micro:"Kongruensi (kata = tubuh)",q:"Kalau kata-katamu berkata 'aku senang bertemu kamu' tapi nada datar & tanpa senyum, lawan bicara cenderung...",options:["Percaya kata-katamu sepenuhnya, karena kata-kata dianggap selalu lebih penting daripada nada & wajahmu","Bingung, & lebih memercayai sinyal tubuh/nada yang terasa dingin","Tidak sadar ada yang aneh sama sekali, sebab orang hanya mendengarkan kata-kata yang kamu ucapkan"],answer:1,explain:"Saat kata & tubuh bertentangan, orang biasanya memercayai yang non-verbal. Selaraskan keduanya.",hint:"Percaya kata, atau percaya nada dingin?"},
{n:23,type:"mcq",micro:"Konteks mengubah arti",q:"Menyilangkan tangan bisa berarti 'menutup diri' — tapi juga bisa berarti...",options:["Selalu berarti sedang berbohong, karena orang jujur tidak pernah menyilangkan tangan saat berbicara","Selalu berarti sedang marah tanpa kecuali, jadi kamu boleh langsung menyimpulkannya dalam keadaan apa pun","Sekadar kedinginan atau posisi nyaman; jangan buru-buru menyimpulkan"],answer:2,explain:"Satu sinyal jarang cukup. Baca kombinasi sinyal + konteks sebelum menafsirkan.",hint:"Satu tafsir pasti, atau lihat konteks & sinyal lain?"},
{n:24,type:"mcq",micro:"Perbedaan budaya",q:"Kontak mata langsung yang lama dianggap sopan di sebagian budaya, tetapi di budaya lain bisa dianggap...",options:["Kurang sopan atau menantang, terutama kepada orang yang lebih tua","Tidak pernah diperhatikan oleh siapa pun, sebab kontak mata tidak punya arti dalam budaya apa pun","Selalu dianggap sopan di mana pun & kepada siapa pun, tanpa pengecualian di budaya mana saja"],answer:0,explain:"Norma non-verbal berbeda antar budaya & keluarga. Perhatikan kebiasaan setempat & orang yang kamu ajak bicara.",hint:"Satu aturan untuk semua budaya, atau berbeda-beda?"},
{n:25,type:"mcq",micro:"Nada menyampaikan perasaan tersembunyi",q:"Teman berkata 'nggak apa-apa kok' dengan suara bergetar & pelan. Kemungkinan besar...",options:["Ia benar-benar baik-baik saja","Ia sedang tidak baik-baik saja & mungkin butuh ditanya lebih lembut","Ia sedang bercanda"],answer:1,explain:"Nada sering membocorkan perasaan yang tidak diucapkan. Tanggapi nada, bukan hanya kata.",hint:"Percaya kata 'nggak apa-apa', atau suara yang bergetar?"},
{n:26,type:"mcq",micro:"Ekspresi mikro",q:"Perubahan wajah sekejap (mis. kerutan dahi cepat) saat kamu bicara bisa menandakan...",options:["Tidak ada apa-apa sama sekali, jadi sebaiknya kamu abaikan saja dan terus berbicara seperti biasa","Lawan bicara pasti sudah marah besar kepadamu, jadi kamu harus segera berhenti dan pergi menjauh","Lawan bicara bingung atau tidak setuju dengan bagian yang baru kamu ucapkan"],answer:2,explain:"Memperhatikan reaksi kecil membantumu berhenti & bertanya: 'Ada yang kurang jelas?'",hint:"Sinyal untuk mengecek pemahaman, atau tanpa arti?"},
{n:27,type:"tf",micro:"Nada bisa membatalkan kata",q:"Benar atau Salah: Kalimat 'bagus sekali' yang diucapkan dengan nada sinis justru menyampaikan ejekan, bukan pujian.",answer:true,explain:"Nada bisa membalik arti kata sepenuhnya. Inilah kenapa sarkasme bekerja — dan kenapa ia mudah menyakiti.",hint:"Nada sinis pada kata pujian — pujian atau ejekan?"},
{n:28,type:"tf",micro:"Semua orang membaca sinyal sama",q:"Benar atau Salah: Setiap orang pasti menafsirkan sinyal bahasa tubuh dengan cara yang persis sama, jadi tidak mungkin terjadi salah paham non-verbal.",answer:false,explain:"Sebaliknya, tafsir sinyal berbeda antar orang & budaya. Diam bisa dibaca 'menghormati' atau 'ngambek'. Saat ragu, tanyakan langsung.",hint:"Tafsir seragam, atau bisa berbeda-beda?"},
{n:29,type:"mcq",micro:"Cermin (mirroring)",q:"Tanpa berlebihan meniru, menyesuaikan sedikit tempo & posisi tubuh dengan lawan bicara cenderung...",options:["Membuat percakapan terasa lebih nyambung & nyaman","Selalu terasa seperti mengejek lawan bicara, sehingga ia akan tersinggung dan menjauh darimu nanti","Membuat lawan bicara marah karena merasa ditiru, sehingga percakapan justru menjadi makin canggung"],answer:0,explain:"'Mirroring' halus & alami membangun rasa 'kita sejalan'. Meniru berlebihan malah terasa aneh.",hint:"Menyesuaikan halus, atau meniru mencolok?"},
{n:30,type:"order",micro:"Menyesuaikan bahasa tubuh saat lawan bicara gelisah",q:"Urutkan cara menenangkan percakapan saat lawan bicara terlihat gelisah/marah.",items:["Perhatikan sinyalnya: napas cepat, suara tinggi, tangan mengepal","Turunkan nada & volume suaramu sendiri, perlambat tempo","Buka postur, jaga jarak nyaman, hindari gerakan tiba-tiba","Akui perasaannya dengan tenang: 'Aku lihat kamu kesal. Aku dengar.'"],answer:[0,1,2,3],explain:"Baca sinyal → tenangkan suaramu → tubuh terbuka & tenang → akui perasaan. Ketenanganmu bisa menular.",hint:"Apa yang kamu perhatikan sebelum menyesuaikan diri?"},
{n:31,type:"mcq",micro:"Wajah 'poker' saat mendengar kabar sulit",q:"Saat teman menceritakan hal berat, wajah yang sepenuhnya datar tanpa reaksi bisa membuatnya merasa...",options:["Sangat didukung","Tidak didengar atau tidak dipedulikan","Lega"],answer:1,explain:"Ekspresi empati ringan (alis sedikit naik, anggukan pelan) memberi tahu 'aku ikut merasakan ini bersamamu'.",hint:"Wajah datar total — mendukung atau terasa dingin?"},
{n:32,type:"tf",micro:"Postur memengaruhi perasaan sendiri",q:"Benar atau Salah: Postur tubuh sama sekali tidak memengaruhi perasaanmu sendiri; menegakkan badan hanya soal kesan bagi orang lain.",answer:false,explain:"Sebaliknya, tubuh & perasaan saling memengaruhi. Postur tegak & napas tenang bisa sedikit menurunkan rasa gugup, bukan hanya mengubah kesan.",hint:"Postur hanya untuk kesan orang, atau juga memengaruhi perasaanmu?"},
{n:33,type:"mcq",micro:"Nada bertanya vs menuduh",q:"'Kenapa kamu telat?' bisa terdengar menuduh. Cara membuatnya terdengar seperti pertanyaan tulus:",options:["Nada rendah yang menekan setiap kata, dengan wajah datar dan pandangan tajam menusuk ke arahnya","Sambil menunjuk wajahnya dan mendekat dengan cepat supaya ia tahu kamu benar-benar ingin jawaban","Nada tenang, sedikit naik di akhir, wajah ingin tahu (bukan mengernyit marah)"],answer:2,explain:"Kata yang sama bisa jadi tuduhan atau rasa ingin tahu — nada & wajah yang menentukan.",hint:"Nada ingin tahu, atau nada menekan?"},
{n:34,type:"mcq",micro:"Bahasa tubuh saat presentasi",q:"Saat presentasi, berdiri tegak, kaki mantap, & sesekali menyapukan pandangan ke seluruh penonton membuat...",options:["Kamu terlihat & terdengar lebih yakin, & penonton merasa disapa","Penonton merasa diabaikan","Kamu terlihat gugup"],answer:0,explain:"Postur mantap + pandangan menyeluruh = pesan 'aku siap & aku bicara untuk kalian semua'.",hint:"Menyapa seluruh penonton, atau menatap satu titik di lantai?"},
{n:35,type:"mcq",micro:"Menutupi mulut / menyentuh wajah",q:"Sering menutupi mulut atau menyentuh hidung saat bicara kadang membuat lawan bicara merasa...",options:["Kamu sangat yakin","Ragu-ragu atau ada yang kamu tahan; juga menyulitkan mereka mendengar","Kamu sedang gembira"],answer:1,explain:"Selain kesan ragu, tangan di depan mulut benar-benar meredam suaramu. Jaga tangan tetap terbuka & rileks.",hint:"Yakin, atau ragu + suara teredam?"},
{n:36,type:"mcq",micro:"Diam yang berbicara",q:"Diam sejenak sambil menatap lembut & mengangguk bisa berarti...",options:["Selalu berarti kamu tidak peduli","Selalu berarti kamu marah","'Aku menyimak, silakan lanjut'"],answer:2,explain:"Diam yang disertai bahasa tubuh hadir adalah bentuk mendengarkan, bukan ketidakpedulian.",hint:"Diam + tubuh hadir — menyimak atau cuek?"},
{n:37,type:"tf",micro:"Nada telepon penting",q:"Benar atau Salah: Di telepon, karena lawan bicara tidak melihat wajahmu, nada suara justru menjadi tidak penting — yang penting hanya isi kata-katamu.",answer:false,explain:"Sebaliknya, tanpa wajah & gestur, suara memikul seluruh beban non-verbal, jadi nada & tempo menjadi lebih penting. Senyum saat menelepon pun terdengar di nada.",hint:"Nada di telepon — lebih penting atau kurang penting?"},
{n:38,type:"mcq",micro:"Membaca kelompok",q:"Saat kamu bicara di depan kelompok & banyak yang menunduk ke HP atau berbisik satu sama lain, itu sinyal...",options:["Perhatian menurun — mungkin perlu jeda, pertanyaan, atau ganti cara","Kamu harus bicara lebih lama lagi tanpa henti sampai semua orang akhirnya memperhatikan kembali","Semua pendengar sudah paham dan setuju dengan penjelasanmu, jadi kamu boleh terus melanjutkan saja"],answer:0,explain:"Bahasa tubuh kelompok adalah umpan balik langsung. Bacalah & sesuaikan.",hint:"Semua baik-baik saja, atau perhatian menurun?"},
{n:39,type:"mcq",micro:"Ekspresi & kejujuran",q:"Melatih agar wajah, nada, & kata selaras berguna karena...",options:["Tidak ada gunanya","Orang merasa lebih mudah memercayaimu & memahami maksudmu","Membuatmu terlihat kaku"],answer:1,explain:"Keselarasan sinyal = 'apa yang kamu lihat adalah apa yang kamu dapat'. Itu dasar kepercayaan.",hint:"Membangun kepercayaan, atau membuat kaku?"},
{n:40,type:"open",micro:"Menganalisis pesan campur",q:"Kakak berkata ke adiknya, 'Iya, iya, nanti kakak bantuin' — tapi sambil menghela napas panjang, tetap menatap HP, dan nadanya ketus. Jelaskan pesan apa yang sebenarnya diterima adik, mengapa, dan bagaimana kakak bisa menyelaraskan kata & bahasa tubuhnya.",explain:"Jawaban baik menyimpulkan bahwa adik menerima pesan negatif dari sinyal non-verbal (terganggu/menolak), menjelaskan bahwa saat kata & tubuh bertentangan orang memercayai yang non-verbal, lalu memberi cara menyelaraskan: singkirkan HP, menghadap, nada tenang, atau jujur soal waktu.",hint:"Bandingkan pesan kata vs pesan tubuh/nada; sebut mana yang dipercaya; beri cara menyelaraskan.",sample:"Meskipun kata-katanya berkata 'iya, nanti kakak bantu', bahasa tubuh dan nadanya (menghela napas, tidak menoleh, nada ketus) menyampaikan pesan sebaliknya: 'aku terganggu dan sebenarnya tidak mau'. Adik kemungkinan besar menerima pesan non-verbal itu, jadi ia merasa ditolak atau menjadi beban, meski secara kata ia 'dijanjikan' bantuan. Ini terjadi karena saat kata dan sinyal tubuh bertentangan, orang cenderung memercayai sinyal tubuh dan nada. Kakak bisa menyelaraskannya dengan: meletakkan HP sebentar, menoleh dan menatap adik, lalu berkata dengan nada tenang 'Oke, kakak selesaikan ini lima menit lagi ya, terus kakak bantu.' Kalau memang sedang tidak bisa, lebih jujur berkata jelas kapan bisa, daripada mengiakan dengan nada ketus."},
{n:41,type:"mcq",micro:"Skenario: wawancara / bertemu orang penting",q:"Saat pertama bertemu kepala sekolah untuk suatu keperluan, bahasa tubuh yang tepat:",options:["Menunduk terus, suara nyaris tak terdengar, tangan dimasukkan ke saku, dan cepat-cepat pergi setelahnya","Bersandar santai di kursi sambil melihat HP dan menjawab sekadarnya dengan nada setengah mengantuk","Berdiri tegak, senyum sopan, kontak mata wajar, salaman/menyapa dengan nada jelas & tenang"],answer:2,explain:"Postur tegak + nada tenang menyampaikan hormat & kesiapan tanpa harus kaku.",hint:"Tegak + sopan + kontak mata, atau menunduk / terlalu santai?"},
{n:42,type:"mcq",micro:"Skenario: menghibur teman menangis",q:"Teman menangis di sebelahmu. Bahasa tubuh yang menghibur:",options:["Duduk mendekat, badan menghadapnya, nada lembut & pelan, mungkin tangan di bahu bila ia nyaman","Berdiri jauh darinya sambil berkata keras-keras 'udah, jangan nangis, malu dilihat orang tahu!'","Menatap HP sambil sesekali berkata 'sabar ya' dengan nada datar tanpa menoleh kepadanya sedikit pun"],answer:0,explain:"Kehadiran fisik yang tenang & nada lembut lebih menghibur daripada kata-kata dari jarak jauh.",hint:"Dekat + lembut + menghadap, atau jauh + keras?"},
{n:43,type:"mcq",micro:"Skenario: menyampaikan ketidaksetujuan",q:"Kamu tidak setuju usul teman di rapat. Bahasa tubuh yang menjaga hubungan:",options:["Menyilangkan tangan erat di dada & memalingkan badan dari temanmu sambil menghela napas panjang","Nada tenang, wajah netral (bukan mencibir), badan tetap menghadap, tangan terbuka","Memutar mata dan mendengus keras supaya semua orang tahu kamu tidak setuju dengan usul tersebut"],answer:1,explain:"Kamu bisa menolak ide dengan tubuh yang tetap sopan & terbuka, sehingga orangnya tidak merasa diserang.",hint:"Tenang + terbuka, atau memutar mata + memalingkan badan?"},
{n:44,type:"mcq",micro:"Skenario: berbicara ke anak kecil",q:"Menjelaskan sesuatu ke anak berumur 5 tahun, bahasa tubuh yang membantu:",options:["Berdiri tinggi menjulang di depannya sambil bicara cepat dengan kalimat-kalimat yang panjang dan rumit","Menunjuk-nunjuk wajahnya sambil bersuara keras supaya ia takut dan langsung menurut kepada penjelasanmu","Berjongkok setara matanya, nada hangat & pelan, ekspresi wajah ramah"],answer:2,explain:"Menyetarakan tinggi mata & nada lembut membuat anak merasa aman & lebih mudah menyimak.",hint:"Setara mata + hangat, atau menjulang + cepat?"},
{n:45,type:"order",micro:"Menyiapkan bahasa tubuh sebelum presentasi",q:"Urutkan langkah menyiapkan bahasa tubuh sebelum tampil di depan kelas.",items:["Tarik napas dalam beberapa kali untuk menenangkan tubuh","Berdiri tegak, kaki selebar bahu, bahu rileks","Mulai dengan senyum & sapukan pandangan ke seluruh kelas","Bicara dengan tempo tenang, gunakan gestur tangan yang sesuai isi"],answer:[0,1,2,3],explain:"Napas → postur → kontak mata & senyum → tempo & gestur. Tubuh yang tenang membuat suara lebih mantap.",hint:"Apa yang pertama menenangkan tubuh?"},
{n:46,type:"mcq",micro:"Skenario: teman bercanda kelewatan",q:"Teman terus mengejek dengan nada 'bercanda'. Bahasa tubuh & nada untuk menunjukkan kamu serius:",options:["Berhenti tersenyum, tatap matanya, nada tenang tapi tegas: 'Aku nggak nyaman dengan candaan itu. Tolong stop.'","Ikut tertawa bersama mereka padahal sebenarnya kamu tidak suka, supaya suasana tetap terlihat santai","Berteriak keras-keras dan mendorong tubuhnya supaya ia kapok dan tidak berani mengulangi lagi besok"],answer:0,explain:"Menurunkan senyum + nada tegas + kontak mata menandakan 'ini bukan main-main' tanpa harus agresif.",hint:"Wajah serius + nada tegas, atau ikut tertawa / agresif?"},
{n:47,type:"mcq",micro:"Skenario: menyambut murid baru",q:"Ada murid baru berdiri sendirian. Bahasa tubuh menyambut:",options:["Berbisik dengan temanmu sambil menatap murid baru itu dari jauh dan menahan senyum diam-diam","Menoleh & tersenyum, melambai atau mendekat, badan menghadap, nada ramah: 'Hai, kamu murid baru ya? Sini gabung.'","Melihat sekilas lalu langsung berbalik badan dan melanjutkan obrolan seolah tidak ada siapa pun di sana"],answer:1,explain:"Sinyal 'kamu terlihat & kamu diterima' seringkali soal menoleh, senyum, & membuka ruang.",hint:"Menoleh + senyum + membuka ruang, atau melirik lalu berbalik?"},
{n:48,type:"mcq",micro:"Skenario: dimarahi tapi kamu tidak salah",q:"Seseorang memarahimu dengan nada tinggi. Bahasa tubuh yang tidak memperkeruh:",options:["Membalas berteriak dengan nada yang sama tingginya sambil maju mendekat supaya ia tahu kamu tidak takut","Memutar mata dan pergi begitu saja tanpa berkata apa pun supaya ia merasa semakin diabaikan olehmu","Tetap tenang, jaga jarak, tangan terbuka di samping, nada rendah: 'Aku dengar kamu marah. Boleh kita bicara pelan-pelan?'"],answer:2,explain:"Tubuh & suara yang tenang bisa menurunkan tensi. Menantang secara fisik/nada justru menaikkannya.",hint:"Tenang + jarak + suara rendah, atau balas berteriak?"},
{n:49,type:"mcq",micro:"Skenario: video call kelompok",q:"Saat rapat lewat video call, agar tetap terlihat menyimak:",options:["Nyalakan kamera, hadapkan wajah ke layar, angguk sesekali, hindari terlihat mengetik hal lain","Mematikan kamera dan mengerjakan tugas lain diam-diam selama rapat berlangsung tanpa ada yang tahu","Menatap ke luar jendela atau ke arah lain sepanjang rapat sambil sesekali bergumam tanpa menyimak"],answer:0,explain:"Di video call, wajah di layar & anggukan adalah satu-satunya bahasa tubuh yang terlihat tim.",hint:"Wajah menghadap + angguk, atau kamera mati + sibuk sendiri?"},
{n:50,type:"open",micro:"Merancang penyesuaian bahasa tubuh",q:"Kamu cenderung berbicara cepat, jarang menatap lawan bicara, dan sering menyilangkan tangan tanpa sadar — sehingga beberapa teman mengira kamu 'jutek'. Rancang 4 penyesuaian bahasa tubuh & nada yang akan kamu latih, dan bagaimana kamu akan mengingatkan diri sendiri.",explain:"Jawaban baik menyebut 4 penyesuaian konkret (mis. melambatkan tempo + jeda, kontak mata wajar, tangan terbuka/tidak menyilang, senyum + anggukan) DAN cara mengingatkan diri (catatan pengingat, cek setelah percakapan, minta umpan balik teman).",hint:"Sasar tempo, kontak mata, posisi tangan, dan ekspresi; lalu buat pengingat yang nyata.",sample:"Empat penyesuaian: (1) Melambatkan tempo bicara dan memberi jeda setelah kalimat penting — supaya tidak terkesan buru-buru atau tidak sabar. (2) Membuat kontak mata wajar: melihat mata lawan bicara beberapa detik, lalu boleh mengalihkan pandangan sebentar, lalu kembali — supaya terlihat hadir dan tertarik. (3) Menjaga tangan tetap rileks di samping atau memegang buku/pulpen alih-alih menyilangkannya — supaya postur terbaca terbuka. (4) Menambahkan senyum kecil saat menyapa dan mengangguk saat orang bicara — supaya sinyal 'ramah' ikut terkirim. Cara mengingatkan diri: menempel catatan kecil 'pelan – mata – tangan – senyum' di sampul buku, dan setiap habis percakapan penting, cek dalam hati apakah aku melakukan keempatnya; minta satu teman dekat memberi kode kalau aku terlihat 'menutup'."},
{n:51,type:"mcq",micro:"Skenario: menawarkan bantuan",q:"Menawarkan bantuan ke teman yang kesulitan, agar tidak terkesan menggurui:",options:["Memakai nada mengasihani sambil menggeleng-geleng pelan seolah ia tidak akan pernah bisa menyelesaikannya","Nada setara & ramah, tubuh di sampingnya (bukan berdiri mengawasi dari atas): 'Mau kubantu bareng?'","Berdiri di belakangnya sambil menunjuk-nunjuk kesalahannya dengan nada tinggi supaya ia segera memperbaikinya"],answer:1,explain:"Posisi tubuh 'di samping' & nada setara menyampaikan 'kita satu tim', bukan 'aku menilaimu'.",hint:"Di samping + setara, atau di atas + menunjuk?"},
{n:52,type:"tf",micro:"Menyesuaikan volume dengan lawan bicara",q:"Benar atau Salah: Kalau lawan bicara berbicara dengan lembut & pelan, menurunkan volume suaramu agar sepadan biasanya membuat percakapan terasa lebih nyaman.",answer:true,explain:"Menyamakan 'energi suara' secara wajar membuat percakapan terasa selaras. Suara jauh lebih keras dari lawan bicara bisa terasa menekan.",hint:"Menyelaraskan volume, atau memaksakan volumemu sendiri?"},
{n:53,type:"mcq",micro:"Skenario: menyampaikan berita gembira",q:"Mengabari teman bahwa ia lolos seleksi, bahasa tubuh yang cocok:",options:["Memakai nada datar sambil berkata 'Oh iya, kamu lolos' tanpa ekspresi apa pun di wajahmu","Menyampaikannya sambil lalu tanpa menatap matanya, seakan-akan itu kabar yang tidak terlalu penting","Wajah cerah, nada bersemangat, mungkin tepuk tangan kecil: 'Kabar bagus! Kamu lolos!'"],answer:2,explain:"Energi tubuh & nada yang sesuai isi berita membuat kabar gembira benar-benar terasa gembira.",hint:"Energi sesuai berita, atau datar?"},
{n:54,type:"mcq",micro:"Skenario: lawan bicara lebih tua",q:"Berbicara dengan orang yang jauh lebih tua (mis. kakek tetangga), penyesuaian yang sopan:",options:["Nada hormat & jelas, tidak memotong, sabar menunggu; kontak mata secukupnya sesuai kebiasaan setempat","Bicara cepat & santai seperti kepada teman sebaya supaya suasana terasa akrab dan tidak terlalu kaku","Berteriak sangat keras karena menganggap semua orang yang sudah tua pasti tidak dapat mendengar dengan baik"],answer:0,explain:"Menyesuaikan tempo, nada hormat, & kesabaran adalah bentuk penghargaan. Jangan berasumsi soal pendengaran.",hint:"Hormat + sabar + jelas, atau cepat / berteriak asal?"},
{n:55,type:"mcq",micro:"Skenario: kamu yang gugup",q:"Kamu gugup menghadap panitia lomba & tangan gemetar. Trik bahasa tubuh untuk membantu diri sendiri:",options:["Bicara sangat cepat tanpa jeda supaya semuanya cepat selesai sebelum tanganmu makin gemetar & terlihat","Pijak lantai dengan mantap, tarik napas panjang 2-3 kali, tegakkan badan, bicara sedikit lebih lambat","Menyilangkan tangan erat-erat di dada sambil menunduk dalam-dalam supaya panitia tidak melihat wajah gugupmu"],answer:1,explain:"Postur mantap + napas panjang menenangkan tubuh, & tubuh yang lebih tenang membuat suara lebih stabil.",hint:"Napas + tegak + lambat, atau menyilang + menunduk + cepat?"},
{n:56,type:"mcq",micro:"Skenario: teman curhat sambil jalan",q:"Teman curhat serius sambil kalian berjalan. Untuk menunjukkan kamu menyimak lewat tubuh:",options:["Mempercepat langkah supaya cepat sampai tujuan dan percakapan serius itu tidak terlalu lama berlangsung","Terus melihat ke sekeliling dan sibuk membalas pesan di HP sambil sesekali berkata 'hmm' kepadanya","Perlambat langkah, sesekali menoleh menatapnya & mengangguk, kurangi lihat HP"],answer:2,explain:"Bahkan sambil berjalan, menoleh & memperlambat langkah menyampaikan 'aku fokus pada ceritamu'.",hint:"Perlambat + menoleh, atau percepat + sibuk HP?"},
{n:57,type:"tf",micro:"Ekspresi berlebihan bisa terasa palsu",q:"Benar atau Salah: Semakin besar & sering gestur serta ekspresimu, semakin tulus & jelas komunikasimu terasa bagi orang lain.",answer:false,explain:"Sebaliknya, bahasa tubuh yang baik itu wajar & sesuai isi. Terlalu sedikit terasa dingin; terlalu banyak (senyum menempel, gestur tak henti) terasa dibuat-buat.",hint:"Berlebihan = selalu lebih baik?"},
{n:58,type:"mcq",micro:"Skenario: menyampaikan permintaan maaf",q:"Meminta maaf dengan sungguh-sungguh, bahasa tubuh & nada:",options:["Menghadap orangnya, kontak mata, nada tenang & pelan, tidak buru-buru pergi setelahnya","Mengucapkannya sambil lewat saja tanpa menoleh sedikit pun, dengan nada cepat supaya tidak canggung","Mengucapkannya sambil tertawa-tawa kecil supaya suasana terasa ringan dan masalahnya tidak dibesar-besarkan"],answer:0,explain:"Permintaan maaf yang tulus terlihat dari tubuh yang berhenti, menghadap, & nada yang serius.",hint:"Berhenti + menghadap + serius, atau sambil lalu?"},
{n:59,type:"mcq",micro:"Skenario: menolak ajakan dengan sopan",q:"Menolak ajakan teman tanpa menyakiti, lewat bahasa tubuh:",options:["Tertawa seperti meremehkan ajakannya, lalu berkata 'ah, nggak mau ah, nggak seru' tanpa penjelasan","Nada hangat, wajah menyesal tulus, kontak mata: 'Maaf ya, aku nggak bisa kali ini. Lain kali ya.'","Memakai nada dingin dan wajah datar sambil berbalik pergi tanpa menjelaskan alasanmu menolak ajakannya"],answer:1,explain:"Penolakan terasa jauh lebih baik bila nada & wajah menunjukkan kamu tetap menghargai orang & ajakannya.",hint:"Hangat + menyesal tulus, atau dingin + berbalik?"},
{n:60,type:"open",micro:"Skenario menyeluruh",q:"Kamu memimpin diskusi kelompok 15 menit. Salah satu anggota (Fira) tampak menyilangkan tangan, menjawab pendek, dan badannya mengarah ke pintu. Rancang bagaimana kamu membaca sinyalnya dan menyesuaikan bahasa tubuh & nadamu sendiri untuk membuatnya lebih nyaman & ikut terlibat (minimal 4 langkah).",explain:"Jawaban baik: menafsirkan sinyal Fira dengan hati-hati (bosan/tidak nyaman/tidak didengar/ada urusan, bukan langsung 'marah'), lalu menyebut penyesuaian bahasa tubuh & nada sendiri yang konkret: tempo turun, postur terbuka & setara, senyum, undangan hangat tanpa menekan, menghadap penuh & mengangguk saat ia bicara, cek pribadi setelahnya.",hint:"Baca sinyal tanpa menghakimi; lalu sesuaikan tempo, postur, senyum, cara mengundang, dan cara mendengar.",sample:"(1) Membaca sinyal Fira: tangan menyilang, jawaban pendek, badan ke arah pintu — kemungkinan ia bosan, tidak nyaman, merasa tidak didengar, atau ada urusan lain. Aku tidak langsung menyimpulkan marah. (2) Menyesuaikan bahasa tubuhku: menurunkan tempo bicara, membuka postur, tidak berdiri mengawasi tapi duduk setara, dan tersenyum ramah ke seluruh kelompok termasuk dia. (3) Memberi Fira ruang & undangan yang tidak menekan: menatapnya dengan ramah lalu berkata dengan nada hangat 'Fira, aku pengin dengar pendapatmu soal ini — nggak apa-apa kalau masih dipikir.' (4) Saat ia mulai bicara, aku menghadapkan badan penuh ke arahnya, mengangguk, tidak memotong, dan tidak melihat HP. (5) Kalau badannya masih mengarah ke pintu, aku bisa bertanya pelan secara pribadi setelahnya 'kamu keliatan buru-buru, ada yang perlu dibantu?' — mungkin memang ada urusan. (6) Aku menjaga nada seluruh diskusi tetap tenang dan tidak terburu, supaya suasananya terasa aman untuk bicara."},
{n:61,type:"mcq",micro:"Mengapa non-verbal begitu kuat",q:"Mengapa sinyal non-verbal (nada, wajah, tubuh) sering lebih dipercaya daripada kata-kata?",options:["Karena kata-kata tidak pernah penting, sehingga orang hanya memperhatikan wajah dan nada suara saja","Karena orang malas mendengarkan kata-kata yang panjang, jadi mereka selalu memilih melihat gerakan saja","Sinyal itu lebih sulit dipalsukan & muncul lebih cepat/otomatis, jadi terasa lebih jujur"],answer:2,explain:"Wajah & nada bereaksi sebelum kita sempat 'mengedit'. Itu sebabnya ketidakcocokan kata-tubuh terasa mencurigakan.",hint:"Lebih sulit dipalsukan & lebih cepat — jujur atau tidak?"},
{n:62,type:"mcq",micro:"Membedakan menafsir & memastikan",q:"Cara aman menggunakan pembacaan bahasa tubuh:",options:["Jadikan dugaan awal ('sepertinya dia tidak nyaman'), lalu pastikan dengan bertanya, bukan langsung yakin","Yakini 100% tafsiranmu dan langsung bertindak berdasarkan tafsiran itu tanpa perlu bertanya apa pun","Abaikan seluruh sinyal tubuh orang lain karena sinyal itu pasti selalu salah dan tidak berguna sama sekali"],answer:0,explain:"Bahasa tubuh memberi petunjuk, bukan bukti. 'Kamu kelihatan agak lelah, benar nggak?' lebih aman daripada asumsi.",hint:"Dugaan yang dikonfirmasi, atau kesimpulan pasti?"},
{n:63,type:"tf",micro:"Bahasa tubuh & kesan pertama",q:"Benar atau Salah: Dalam beberapa detik pertama bertemu, orang sudah membentuk kesan besar tentangmu dari postur, ekspresi wajah, & nada sapaanmu.",answer:true,explain:"Kesan pertama terbentuk cepat & sebagian besar dari sinyal non-verbal. Kabar baiknya: kesan itu bisa diperbaiki lewat interaksi selanjutnya.",hint:"Kesan pertama lambat & dari kata, atau cepat & dari non-verbal?"},
{n:64,type:"mcq",micro:"Menilai keselarasan",q:"Seseorang berkata 'aku sangat tertarik' tapi terus melirik jam & badannya menjauh. Kesimpulan yang masuk akal:",options:["Ia pasti membencimu","Ada ketidakcocokan; mungkin ia sopan tapi sebenarnya ingin mengakhiri — beri ruang atau tawarkan lanjut nanti","Ia benar-benar sangat tertarik"],answer:1,explain:"Saat kata & tubuh tak sejalan, sesuaikan diri dengan lembut — jangan memaksakan percakapan.",hint:"Percaya kata, atau baca ketidakcocokannya?"},
{n:65,type:"mcq",micro:"Mengapa nada memengaruhi konflik",q:"Dalam pertengkaran, menaikkan volume & mempercepat nada biasanya...",options:["Membuat lawan langsung setuju","Menenangkan lawan","Membuat lawan ikut naik & percakapan makin panas"],answer:2,explain:"Nada menular. Menurunkan volume & memperlambat sering menjadi rem pertama sebuah pertengkaran.",hint:"Nada tinggi menular ke arah mana?"},
{n:66,type:"tf",micro:"Konteks & sinyal tunggal",q:"Benar atau Salah: Satu sinyal tubuh saja (mis. tangan menyilang) sudah cukup untuk memastikan perasaan seseorang; tidak perlu melihat sinyal lain atau konteksnya.",answer:false,explain:"Sebaliknya, menyilangkan tangan bisa berarti kedinginan, kebiasaan, atau nyaman. Baca kelompok sinyal + konteks sebelum menyimpulkan.",hint:"Satu sinyal cukup, atau butuh gambaran utuh?"},
{n:67,type:"mcq",micro:"Bahasa tubuh & rasa percaya diri",q:"Hubungan antara postur & perasaan:",options:["Dua arah: perasaan memengaruhi postur, & postur juga sedikit memengaruhi perasaan","Hanya satu arah saja: perasaan memengaruhi postur, tetapi postur tidak pernah memengaruhi perasaan siapa pun","Tidak ada hubungan sama sekali antara postur tubuh dan perasaan, keduanya berjalan sendiri-sendiri tanpa saling memengaruhi"],answer:0,explain:"Menegakkan badan & bernapas tenang saat gugup bisa sedikit menurunkan rasa gugup itu sendiri.",hint:"Postur bisa memengaruhi perasaan balik?"},
{n:68,type:"mcq",micro:"Sarkasme & risiko salah paham",q:"Mengapa sarkasme (kata positif + nada negatif) berisiko dalam komunikasi?",options:["Sarkasme tidak pernah disalahmengerti oleh siapa pun, karena semua orang otomatis bisa menangkap maksud aslinya","Kalau lawan bicara tidak menangkap nadanya (atau lewat teks), ia bisa salah paham atau merasa dibohongi lalu diejek","Sarkasme selalu lucu bagi semua orang yang mendengarnya, jadi tidak ada risiko apa pun dalam memakainya"],answer:1,explain:"Sarkasme sepenuhnya bergantung pada nada. Hilang nadanya (teks) atau meleset tangkapannya, ia menyakiti atau membingungkan.",hint:"Kalau nadanya tidak tertangkap, apa yang terjadi?"},
{n:69,type:"mcq",micro:"Menyesuaikan tanpa kehilangan diri",q:"Menyesuaikan bahasa tubuh dengan situasi (lebih formal ke guru, lebih santai ke teman) berarti...",options:["Kamu sedang berpura-pura dan tidak jujur, karena orang yang tulus pasti selalu bersikap sama persis di mana saja","Kamu harus selalu bersikap sama persis di semua situasi, kalau tidak berarti kamu tidak punya pendirian yang kuat","Kamu peka konteks — bukan berarti kamu palsu atau kehilangan jati diri"],answer:2,explain:"Sama seperti memilih pakaian sesuai acara, menyesuaikan sinyal sosial adalah kepekaan, bukan kepalsuan.",hint:"Peka konteks, atau palsu?"},
{n:70,type:"order",micro:"Dari salah baca ke klarifikasi",q:"Urutkan proses ketika kamu salah membaca bahasa tubuh seseorang.",items:["Sadari tafsiranmu hanya dugaan ('kupikir dia marah padaku')","Perhatikan lagi: sinyal lain & konteksnya mendukung atau tidak?","Tanyakan dengan lembut: 'Aku ngerasa ada yang kurang enak, benar nggak?'","Sesuaikan sikapmu berdasarkan jawabannya, bukan berdasarkan dugaan awal"],answer:[0,1,2,3],explain:"Sadar itu dugaan → cek sinyal lain → konfirmasi → sesuaikan berdasarkan fakta. Jangan bertindak atas tebakan.",hint:"Apa langkah pertama sebelum bertanya?"},
{n:71,type:"mcq",micro:"Bahasa tubuh pemimpin",q:"Mengapa pemimpin kelompok yang baik memperhatikan bahasa tubuh anggotanya?",options:["Ia menangkap kebingungan, kelelahan, atau ketidaksetujuan yang belum diucapkan, lalu bisa menanyakannya","Untuk mencari siapa yang bisa dihukum","Tidak ada gunanya"],answer:0,explain:"Banyak masalah tim muncul sebagai sinyal tubuh sebelum jadi kata. Pemimpin peka bisa turun tangan lebih awal.",hint:"Menangkap masalah dini, atau mencari kesalahan?"},
{n:72,type:"tf",micro:"Non-verbal bisa dilatih",q:"Benar atau Salah: Kebiasaan bahasa tubuh & nada bisa diperbaiki dengan kesadaran, latihan, dan umpan balik dari orang yang dipercaya.",answer:true,explain:"Merekam diri, meminta teman jujur, & berlatih di percakapan kecil semuanya membantu.",hint:"Bawaan tetap, atau bisa dilatih?"},
{n:73,type:"mcq",micro:"Ketika tubuh & kata sengaja beda",q:"Kadang orang sengaja menahan ekspresi (mis. tetap tenang saat marah demi menjaga situasi). Ini...",options:["Berarti orang itu sama sekali tidak punya perasaan, karena perasaan yang asli pasti langsung terlihat di wajahnya","Bisa jadi pilihan dewasa, selama perasaan itu tetap diakui & disalurkan dengan sehat nanti","Selalu merupakan kebohongan dan sikap yang buruk, karena orang yang jujur harus menampakkan semua perasaannya segera"],answer:1,explain:"Mengatur ekspresi berbeda dari memendam beracun. Yang sehat: kelola sekarang, proses & sampaikan kemudian.",hint:"Mengatur ekspresi sementara = selalu bohong?"},
{n:74,type:"mcq",micro:"Menilai ruang pribadi",q:"Bagaimana tahu jarak berdiri yang pas dengan seseorang?",options:["Selalu berdiri sedekat mungkin dengan semua orang supaya terlihat akrab dan mudah dipercaya oleh mereka","Selalu berdiri sejauh mungkin dari semua orang supaya mereka tidak pernah merasa terganggu oleh kehadiranmu","Perhatikan reaksinya: kalau ia mundur, beri jarak; kalau nyaman, pertahankan"],answer:2,explain:"Ruang pribadi berbeda tiap orang & situasi. Bacalah & hormati.",hint:"Baca reaksi, atau satu jarak untuk semua?"},
{n:75,type:"tf",micro:"Senyum saat menelepon",q:"Benar atau Salah: Tersenyum saat berbicara di telepon sebenarnya sia-sia karena lawan bicara tidak bisa melihatnya.",answer:false,explain:"Sebaliknya, senyum sedikit mengubah bentuk mulut & pita suara sehingga suaramu terdengar lebih hangat & ramah di telinga lawan bicara.",hint:"Senyum di telepon — terdengar atau tidak?"},
{n:76,type:"mcq",micro:"Bahasa tubuh & empati",q:"Saat menyimak cerita sedih, mencondongkan badan sedikit & melambatkan gerak berfungsi...",options:["Menyampaikan 'aku hadir sepenuhnya untukmu sekarang'","Menekan pembicara supaya cepat menyelesaikan ceritanya, karena kamu ingin segera berpindah ke topik lain","Membuatmu terlihat mengantuk dan malas menanggapi sehingga pembicara memilih berhenti bercerita padamu"],answer:0,explain:"Tubuh yang melambat & mendekat adalah bahasa 'aku bersamamu di momen ini'.",hint:"Hadir penuh, atau menekan?"},
{n:77,type:"mcq",micro:"Ketidakcocokan sebagai sinyal",q:"Kalau kamu merasa 'ada yang aneh' saat orang berbicara meski kata-katanya normal, sering itu karena...",options:["Orang itu pasti sedang berbohong tentang segala hal yang ia katakan, jadi kamu tidak perlu percaya lagi","Otakmu menangkap ketidakcocokan halus antara kata & nada/wajahnya — layak dicek dengan lembut","Kamu hanya berlebihan dan terlalu curiga, jadi sebaiknya kamu langsung mengabaikan perasaan itu sepenuhnya"],answer:1,explain:"Rasa 'ada yang ganjil' sering merupakan pembacaan non-verbal bawah sadar. Tanggapi dengan pertanyaan lembut, bukan tuduhan.",hint:"Instingmu menangkap ketidakcocokan, atau kamu mengada-ada?"},
{n:78,type:"mcq",micro:"Bahasa tubuh & inklusi",q:"Dalam kelompok, bahasa tubuh yang membuat semua anggota merasa disertakan:",options:["Hanya menatap dan menghadap satu-dua orang favoritmu sepanjang diskusi, sedangkan yang lain dibiarkan saja","Menghadap ke dinding atau ke papan tulis sambil berbicara, tanpa pernah menoleh ke arah anggota kelompok lain","Menyapukan kontak mata ke semua orang secara bergiliran, badan tidak membelakangi siapa pun, mengangguk saat tiap orang bicara"],answer:2,explain:"Arah tubuh & pandangan menentukan siapa yang merasa 'termasuk' dalam percakapan.",hint:"Menyapa semua dengan pandangan, atau hanya beberapa?"},
{n:79,type:"mcq",micro:"Menilai nada pesan suara",q:"Sebelum mengirim voice note yang berisi kritik, memeriksa nadamu penting karena...",options:["Nada yang tanpa sadar terdengar ketus/menyindir bisa menyakiti lebih dari isi kritiknya sendiri","Nada suara tidak terdengar sama sekali di dalam voice note, jadi kamu tidak perlu memperhatikannya","Isi kritik selalu jauh lebih penting daripada nadanya, jadi cara mengucapkannya tidak perlu dipikirkan lagi"],answer:0,explain:"Voice note membekukan nadamu. Dengarkan ulang: apakah terdengar seperti membantu atau menyerang?",hint:"Nada di voice note — hilang atau terekam & berpengaruh?"},
{n:80,type:"open",micro:"Membandingkan dua penyampai kabar buruk",q:"Dua guru menyampaikan bahwa study tour dibatalkan. Bu Ana: berdiri jauh, nada datar-cepat, tidak menatap murid, langsung pergi. Pak Budi: berdiri di depan kelas menghadap murid, nada tenang & menyesal, menatap sekeliling, memberi jeda untuk reaksi, dan tinggal untuk menjawab pertanyaan. Jelaskan bagaimana bahasa tubuh & nada tiap guru memengaruhi bagaimana murid menerima kabar itu, dan pelajaran apa yang bisa kamu ambil.",explain:"Jawaban baik mengontraskan efek kedua gaya: Bu Ana membuat murid merasa tak dipedulikan (menambah kekesalan), Pak Budi membuat murid merasa dihargai (lebih mudah menerima), lalu menarik pelajaran bahwa untuk kabar buruk, bahasa tubuh menghadap + nada tenang-empatik + jeda + kesediaan menjawab sangat menentukan penerimaan.",hint:"Bandingkan pesan tersembunyi tiap gaya ('kalian tak penting' vs 'aku bersama kalian') dan efeknya pada penerimaan.",sample:"Bahasa tubuh dan nada Bu Ana (jauh, datar-cepat, tidak menatap, langsung pergi) membuat murid merasa kabar itu disampaikan tanpa peduli pada perasaan mereka, seolah mereka tidak penting. Kekecewaan murid bisa berubah jadi kesal pada cara penyampaiannya, bukan hanya pada isinya. Pak Budi, dengan menghadap murid, nada tenang dan menyesal, menatap sekeliling, memberi jeda, dan tinggal menjawab pertanyaan, menyampaikan 'aku tahu ini mengecewakan, dan aku di sini bersama kalian'. Isinya sama-sama kabar buruk, tapi murid merasa dihargai dan lebih mudah menerima. Pelajaran: saat menyampaikan kabar yang tidak menyenangkan, isi harus tetap jelas, tetapi bahasa tubuh yang menghadap, nada tenang-empatik, jeda untuk reaksi, dan kesediaan tinggal untuk menjawab sangat menentukan apakah pesan diterima dengan lapang atau dengan kemarahan tambahan."},
{n:81,type:"mcq",micro:"Kasus: bahasa tubuh di persidangan kelas / mediasi",q:"Kamu menengahi dua teman yang bertikai. Bahasa tubuh yang menjaga kamu terlihat netral:",options:["Menyilangkan tangan dan menghela napas panjang setiap kali salah satu pihak sedang berbicara di depanmu","Duduk di antara/menghadap keduanya secara seimbang, kontak mata bergantian merata, nada tenang yang sama untuk keduanya","Lebih sering menghadap dan mengangguk-angguk kepada salah satu pihak yang menurutmu lebih benar dalam masalah itu"],answer:1,explain:"Netralitas terlihat dari perlakuan tubuh yang setara: pandangan, arah badan, & nada yang seimbang untuk kedua pihak.",hint:"Perlakuan tubuh setara, atau condong ke satu pihak?"},
{n:82,type:"mcq",micro:"Kasus: kamu gugup tapi harus terlihat tenang",q:"Kamu tampil & jantung berdebar, tapi ingin terlihat cukup tenang untuk menenangkan tim. Yang bisa kamu kendalikan:",options:["Tidak ada yang bisa dilakukan sama sekali, jadi pasrah saja pada rasa panik sampai penampilan selesai","Bicara sangat cepat tanpa jeda supaya tidak ketahuan tanganmu gemetar & suaramu mulai bergetar di depan tim","Perlambat napas & bicara, tegakkan badan, jeda sebelum menjawab — tubuh yang lebih tenang membantu perasaan & kesan sekaligus"],answer:2,explain:"Kamu tidak bisa langsung memerintah detak jantung, tapi bisa mengatur napas, tempo, & postur — & itu membantu keduanya.",hint:"Atur napas + tempo + postur, atau pasrah / makin cepat?"},
{n:83,type:"tf",micro:"Refleksi: perhatian penuh terbaca",q:"Benar atau Salah: Selama kamu sesekali berkata 'iya', orang tidak bisa membedakan apakah kamu benar-benar memperhatikan atau pikiranmu ada di tempat lain.",answer:false,explain:"Sebaliknya, arah tubuh, kontak mata, & responsivitas wajah sulit dipalsukan — orang biasanya merasakan perbedaan antara perhatian penuh & 'iya' yang kosong.",hint:"Bisa dirasakan bedanya, atau tidak?"},
{n:84,type:"mcq",micro:"Kasus: menegur dengan menjaga martabat",q:"Sebagai ketua, kamu perlu menegur anggota yang lalai. Bahasa tubuh yang menjaga martabatnya:",options:["Bicara berdua di tempat tenang, nada rendah & tenang, badan setara (duduk berhadapan), fokus pada perilaku bukan menghakimi pribadi","Menegur keras-keras di depan semua anggota sambil menunjuk wajahnya supaya yang lain ikut jera dan takut lalai","Menghela napas panjang dan memutar mata setiap kali ia lalai saat rapat berlangsung, tanpa berkata apa-apa kepadanya"],answer:0,explain:"Tempat privat + nada tenang + posisi setara membuat teguran terasa sebagai perbaikan, bukan penghinaan.",hint:"Privat + tenang + setara, atau di depan umum + menunjuk?"},
{n:85,type:"order",micro:"Menyiapkan diri untuk percakapan sulit",q:"Urutkan persiapan bahasa tubuh & nada sebelum percakapan sulit (mis. menyampaikan kekecewaan ke teman).",items:["Tenangkan diri dulu: napas, longgarkan bahu, turunkan detak","Pilih tempat & waktu tenang, duduk setara & menghadap","Buka dengan nada tenang & wajah terbuka, bukan menuduh","Jaga suara tetap rendah & stabil meski pembicaraan memanas; beri jeda"],answer:[0,1,2,3],explain:"Tenangkan diri → atur tempat & posisi → buka dengan tenang → jaga nada stabil. Tubuh yang tenang menjaga percakapan tetap percakapan.",hint:"Apa yang harus tenang lebih dulu — dirimu atau pembicaraannya?"},
{n:86,type:"mcq",micro:"Kasus: perbedaan gaya keluarga",q:"Di keluarga temanmu, bicara dengan suara keras & gestur besar adalah hal biasa & hangat. Di keluargamu itu terasa seperti bertengkar. Sikap yang bijak saat berkunjung:",options:["Memaksa mereka berbicara pelan seperti di rumahmu sendiri, karena cara bicara keluargamu pasti lebih sopan","Sadari bahwa norma non-verbal berbeda antar keluarga; jangan buru-buru menyimpulkan mereka 'marah', & sesuaikan diri seperlunya","Menyimpulkan bahwa keluarga itu kasar dan suka bertengkar, lalu menjauh dan tidak mau berkunjung lagi"],answer:1,explain:"Banyak 'salah paham' non-verbal sebenarnya perbedaan gaya. Kesadaran ini mencegah penilaian yang keliru.",hint:"Beda gaya keluarga, atau mereka pasti marah?"},
{n:87,type:"tf",micro:"Bahasa tubuh & disabilitas",q:"Benar atau Salah: Beberapa orang (mis. sebagian orang autistik) mungkin menunjukkan kontak mata atau ekspresi wajah dengan cara berbeda, dan itu tidak berarti mereka tidak menyimak atau tidak jujur.",answer:true,explain:"Aturan bahasa tubuh 'umum' tidak berlaku sama untuk semua orang. Menyimak & menghargai bisa terlihat berbeda-beda.",hint:"Kontak mata sedikit = pasti tidak menyimak?"},
{n:88,type:"mcq",micro:"Kasus: menyampaikan antusiasme yang tulus",q:"Teman mengundangmu ke acaranya & kamu benar-benar senang. Agar antusiasmemu terasa:",options:["Menjawab 'iya boleh' dengan nada datar karena malu terlihat terlalu bersemangat di depan teman-teman","Menunda menjawab selama berhari-hari supaya terlihat sibuk dan tidak terlalu berharap pada undangan itu","Biarkan wajah & nada mengikuti perasaan: senyum, nada naik, 'Wah, aku mau banget! Kapan?'"],answer:2,explain:"Menahan ekspresi positif bisa membuat orang mengira kamu tidak tertarik. Biarkan tubuh & nada menunjukkan yang kamu rasakan.",hint:"Biarkan tubuh menunjukkan senang, atau tahan sampai datar?"},
{n:89,type:"mcq",micro:"Kasus: membaca sinyal minta tolong",q:"Teman yang biasanya ceria jadi pendiam, bahunya turun, menghindari kontak mata, & tersenyum tipis dipaksakan selama beberapa hari. Respons yang peka:",options:["Dekati secara pribadi dengan nada lembut: 'Aku perhatiin kamu agak beda beberapa hari ini. Aku di sini kalau kamu mau cerita.'","Mengabaikannya saja karena ia tidak mengatakan apa pun, dan menganggap semua orang memang kadang berubah suasana hati sendiri","Menggodanya keras-keras di depan umum supaya ia kembali ceria seperti dulu di hadapan semua teman sekelasnya"],answer:0,explain:"Perubahan pola bahasa tubuh dari kebiasaan seseorang adalah sinyal penting. Menawarkan ruang dengan lembut bisa sangat berarti.",hint:"Perubahan dari kebiasaannya — sinyal untuk didekati atau diabaikan?"},
{n:90,type:"open",micro:"Kasus menyeluruh",q:"Kamu akan memimpin acara perkenalan untuk 30 murid baru selama 10 menit. Tujuanmu: mereka merasa disambut & berani ikut bicara. Rancang penggunaan bahasa tubuh & nada sepanjang acara (minimal 6 hal konkret).",explain:"Jawaban baik menyebut minimal 6 hal konkret: menenangkan tubuh dulu, senyum + pandangan menyeluruh, postur terbuka + bergerak menjangkau semua, nada hangat + tempo + jeda, menghadap penuh + mengangguk saat murid bicara, menghindari sinyal menekan (menunjuk/melipat tangan/lihat jam), gestur mengundang terbuka, penutup hangat.",hint:"Pikirkan tiap tahap: persiapan tubuh, pembukaan, saat kamu bicara, saat murid bicara, sinyal yang dihindari, penutup.",sample:"(1) Sebelum mulai: tarik napas, tegakkan badan, longgarkan bahu — supaya suara stabil dan aku terlihat tenang. (2) Membuka dengan senyum tulus dan menyapukan pandangan ke seluruh ruangan, bukan menatap satu titik — supaya setiap murid merasa disapa. (3) Berdiri dengan postur terbuka (tangan rileks, tidak menyilang), badan menghadap ke arah murid, dan berpindah posisi perlahan agar menjangkau semua sisi ruangan. (4) Nada hangat dan tempo tenang dengan jeda setelah kalimat penting — supaya terasa ramah, bukan buru-buru. (5) Saat seorang murid bicara: menghadapkan badan penuh ke arahnya, kontak mata, mengangguk, tidak memotong — supaya ia merasa didengar dan yang lain melihat bahwa bicara di sini aman. (6) Menghindari sinyal yang menekan: tidak menunjuk-nunjuk, tidak melipat tangan, tidak melihat jam. (7) Menggunakan gestur tangan terbuka saat mengundang ('silakan, siapa yang mau cerita hobinya?') alih-alih menunjuk orang. (8) Menutup dengan senyum, kontak mata menyeluruh, dan nada hangat: 'Senang kenalan sama kalian semua.'"},
{n:91,type:"mcq",micro:"Kasus: nada berbeda untuk pesan sama",q:"Kalimat 'kita perlu bicara' bisa terdengar mengancam. Agar terdengar sebagai ajakan biasa:",options:["Menyampaikannya dengan wajah tegang dan tatapan tajam tanpa memberi penjelasan apa pun tentang topiknya","Nada ringan & hangat, tambahkan konteks: 'Nanti sore ada waktu? Aku mau ngobrolin soal jadwal, santai kok.'","Mengirim persis kalimat 'kita perlu bicara.' tanpa tambahan konteks apa pun, dengan nada yang berat & dingin"],answer:1,explain:"Nada + konteks singkat mengubah kalimat yang bisa memicu cemas menjadi undangan yang tenang.",hint:"Nada ringan + konteks, atau kalimat berat tanpa penjelasan?"},
{n:92,type:"tf",micro:"Refleksi: kecil tapi berdampak",q:"Benar atau Salah: Perubahan kecil seperti menoleh menghadap orang, menurunkan volume saat lawan bicara pelan, atau menambahkan senyum saat menyapa bisa terasa berdampak besar bagi bagaimana orang lain merasa diperlakukan.",answer:true,explain:"Sinyal non-verbal kecil terjadi ratusan kali sehari. Memperbaiki beberapa kebiasaan kecil mengubah kesan keseluruhanmu.",hint:"Perubahan kecil non-verbal — berdampak atau tidak?"},
{n:93,type:"mcq",micro:"Kasus: menjaga wajah ramah saat lelah",q:"Kamu lelah tapi harus melayani tamu/pengunjung. Yang realistis & jujur:",options:["Menampilkan wajah kesal dan nada ketus kepada semua tamu supaya mereka tahu kamu sedang sangat lelah","Memaksakan senyum lebar yang palsu sampai terlihat aneh dan membuat tamu merasa tidak nyaman denganmu","Berusaha menjaga nada ramah & kontak mata dasar; bila benar-benar tak sanggup, minta jeda atau bergantian dengan teman"],answer:2,explain:"Ada ruang tengah antara 'jutek' & 'palsu berlebihan': keramahan dasar yang tulus, plus jujur soal batas dirimu.",hint:"Ramah dasar + jujur soal batas, atau ketus / palsu berlebihan?"},
{n:94,type:"mcq",micro:"Kasus: bahasa tubuh saat menerima kritik",q:"Guru mengkritik pekerjaanmu di depan kelas. Bahasa tubuh yang membantumu tetap tenang & terlihat mau belajar:",options:["Badan menghadap guru, mengangguk pelan, wajah tenang, catat poinnya — bukan memutar mata atau menunduk cemberut","Menyilangkan tangan, memutar mata, dan menghela napas keras supaya guru tahu kamu tidak setuju dengan kritiknya","Menunduk dalam-dalam dan tidak bereaksi sama sekali, seolah-olah kamu tidak mendengar apa pun yang dikatakan guru"],answer:0,explain:"Bahasa tubuh yang terbuka saat dikritik menyampaikan 'aku menyimak & mau memperbaiki', dan itu juga membantu emosimu sendiri.",hint:"Menghadap + angguk + catat, atau memutar mata / menunduk cemberut?"},
{n:95,type:"tf",micro:"Menyelaraskan itu jujur",q:"Benar atau Salah: Berlatih menyelaraskan wajah, nada, dan kata pada dasarnya adalah belajar berakting palsu untuk menutupi perasaan sebenarnya.",answer:false,explain:"Sebaliknya, tujuan keselarasan adalah membuat sinyal luar mencocokkan maksud & perasaan sebenarnya, sehingga orang tidak salah paham — itu kejujuran yang lebih jelas, bukan manipulasi.",hint:"Menyelaraskan = manipulasi, atau kejujuran yang lebih jelas?"},
{n:96,type:"mcq",micro:"Kasus: perbedaan online vs tatap muka",q:"Di grup chat, sebuah kalimat singkat 'ok.' dari temanmu terasa dingin. Sikap yang bijak sebelum tersinggung:",options:["Menyimpulkan bahwa temanmu itu membencimu dan marah padamu, lalu berhenti membalas semua pesannya sejak itu","Ingat bahwa teks kehilangan nada & wajah; 'ok.' mungkin hanya singkat, bukan marah — bila ragu, tanyakan langsung","Langsung membalas dengan ketus, 'Kenapa sih sinis banget?' tanpa memeriksa dulu apa maksud sebenarnya"],answer:1,explain:"Banyak konflik chat lahir karena kita mengisi 'nada yang hilang' dengan tafsir terburuk. Konfirmasi sebelum bereaksi.",hint:"Isi nada yang hilang dengan tafsir buruk, atau konfirmasi dulu?"},
{n:97,type:"mcq",micro:"Prinsip inti bab ini",q:"Pesan inti bahasa tubuh & nada:",options:["Bahasa tubuh tidak penting selama kata-katamu sopan; tafsirkan sinyal orang lain sebagai bukti pasti & jangan pernah bertanya lagi, di situasi apa pun","Tiru gerakan orang lain sepersis & secepat mungkin; sinyal kecil tidak perlu diperhatikan, & satu aturan cukup untuk semua orang dan semua keadaan","Selaraskan kata, nada, & tubuh; baca sinyal orang lain sebagai petunjuk (bukan bukti) & konfirmasi bila ragu; sesuaikan dengan konteks & orang; sinyal kecil berdampak besar"],answer:2,explain:"Ringkasan: keselarasan, membaca sinyal dengan hati-hati, kepekaan konteks, & kesadaran bahwa hal kecil non-verbal banyak berbicara.",hint:"Selaras, baca sebagai petunjuk, sesuaikan konteks, hal kecil berdampak — rangkai."},
{n:98,type:"tf",micro:"Refleksi: dua arah",q:"Benar atau Salah: Menjadi baik dalam bahasa tubuh & nada mencakup dua hal: mengirim sinyal yang selaras dengan maksudmu, DAN membaca sinyal orang lain dengan cermat & rendah hati.",answer:true,explain:"Komunikasi non-verbal adalah percakapan dua arah: apa yang kamu pancarkan & apa yang kamu tangkap.",hint:"Hanya soal mengirim sinyal, atau mengirim + membaca?"},
{n:99,type:"mcq",micro:"Kasus: refleksi harian",q:"Cara melatih kesadaran non-verbal setiap hari:",options:["Setelah percakapan penting, tanya diri: apakah nada & wajahku cocok dengan maksudku? sinyal apa dari lawan bicara yang kulewatkan?","Tidak pernah memikirkannya sama sekali setelah percakapan selesai, karena menurutmu itu hal yang sepele dan tidak perlu dilatih lagi","Menyalahkan orang lain setiap kali terjadi salah paham, sebab kamu yakin dirimu sendiri sudah selalu menyampaikannya dengan tepat"],answer:0,explain:"Refleksi singkat & jujur mengubah interaksi biasa menjadi latihan yang terarah.",hint:"Evaluasi jujur, atau menyalahkan orang lain?"},
{n:100,type:"open",micro:"Refleksi & aturan pribadi",q:"Tulis 'aturan pribadi bahasa tubuh & nada' berisi minimal 5 poin yang akan kamu pegang, masing-masing dengan alasan singkat.",explain:"Jawaban baik memuat minimal 5 aturan konkret dengan alasan, mencakup ide inti bab: menghadap + singkirkan gangguan, selaraskan kata-nada-wajah, turunkan nada saat konflik, baca sinyal sebagai dugaan lalu konfirmasi, sesuaikan dengan konteks, hati-hati menafsir teks, sinyal kecil (senyum/anggukan) yang menyambut.",hint:"Ambil satu pelajaran tiap fase — menghadap, keselarasan, nada saat konflik, membaca sinyal, konteks, teks, hal kecil — jadikan aturan 'aku akan...'.",sample:"Contoh aturan pribadi: (1) Saat seseorang mengajakku bicara, aku menoleh dan menghadapkan badan ke arahnya serta menyingkirkan HP — karena arah tubuh menyampaikan siapa yang penting. (2) Aku menjaga kata, nada, dan wajahku selaras — kalau aku berkata 'tidak apa-apa' padahal kesal, aku memilih jujur — karena orang memercayai nada lebih dari kata. (3) Saat lawan bicara marah, aku menurunkan volume dan memperlambat tempo suaraku — karena nada menular dan ketenangan bisa meredakan. (4) Aku membaca bahasa tubuh orang sebagai dugaan, lalu mengonfirmasi dengan bertanya lembut ('kamu keliatan capek, benar?') — karena satu sinyal mudah salah tafsir. (5) Aku menyesuaikan sinyalku dengan konteks (lebih hormat ke orang tua, lebih santai ke teman) tanpa merasa itu palsu — karena itu kepekaan, bukan kepura-puraan. (6) Di teks, aku tidak buru-buru tersinggung oleh pesan singkat, karena teks kehilangan nada dan wajah. (7) Aku menambahkan senyum saat menyapa dan anggukan saat orang bicara — karena sinyal kecil membuat orang merasa diterima."},
];
